13	// IncrementalSink is a sink for writing locally-generated WAL snapshot data to a Snapshot store.
14	type IncrementalSink struct {
15		dir    string
16		header *proto.Header
17		file   *os.File
18	}
19	
20	// NewIncrementalSink creates a new IncrementalSink object.
21	func NewIncrementalSink(dir string, m *proto.Header) *IncrementalSink {
22		return &IncrementalSink{
23			dir:    dir,
24			header: m,
25		}
26	}
27	
28	// Open opens the sink for writing.
29	func (s *IncrementalSink) Open() error {
30		f, err := os.Create(filepath.Join(s.dir, walfileName))
31		if err != nil {
32			return err
33		}
34		s.file = f
35		return nil
36	}
37	
38	// Write writes data to the sink.
39	func (s *IncrementalSink) Write(p []byte) (n int, err error) {
40		return s.file.Write(p)
41	}
42	
43	// Close closes the sink.
44	//
45	// On Close, the file size and basic validity checks are performed. If
46	// the header includes a CRC32 checksum, that is also verified.
47	func (s *IncrementalSink) Close() error {
48		defer s.file.Close()
49	
50		if err := s.file.Sync(); err != nil {
51			return err
52		}
53	
54		sz, err := fileSize(s.file.Name())
55		if err != nil {
56			return err
57		}
58		if sz != int64(s.header.SizeBytes) {
59			return fmt.Errorf("file size mismatch: got %d, want %d", sz, s.header.SizeBytes)
60		}
61	
62		if !db.IsValidSQLiteWALFile(s.file.Name()) {
63			return fmt.Errorf("file is not a valid SQLite WAL file")
64		}
65	
66		if s.header.Crc32 != 0 {
67			crc32, err := rsum.CRC32(s.file.Name())
68			if err != nil {
69				return err
70			}
71			if crc32 != s.header.Crc32 {
72				return fmt.Errorf("file checksum mismatch: got %d, want %d", crc32, s.header.Crc32)
73			}
74		}
75		return nil
76	}
77	
78	// WALFile returns the path to the installed WAL file.
79	func (s *IncrementalSink) WALFile() string {
80		return s.file.Name()
81	}
