1	package snapshot
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path/filepath"
8	
9		"github.com/rqlite/rqlite/v10/db"
10		"github.com/rqlite/rqlite/v10/snapshot/proto"
11	)
12	
13	var (
14		// ErrSinkOpen indicates that the sink is already open.
15		ErrSinkOpen = errors.New("snapshot sink already open")
16	
17		// ErrSinkNotOpen indicates that the sink is not open.
18		ErrSinkNotOpen = errors.New("snapshot sink not open")
19	
20		// ErrUnexpectedData indicates that the caller wrote more bytes than expected.
21		ErrUnexpectedData = errors.New("no more data expected")
22	
23		// ErrIncomplete indicates Close() was called before all bytes were written.
24		ErrIncomplete = errors.New("snapshot install incomplete")
25	
26		// ErrHeaderInvalid indicates the header is invalid.
27		ErrHeaderInvalid = errors.New("snapshot install header invalid")
28	
29		// ErrInvalidSQLiteFile indicates the installed DB file is not a valid SQLite file.
30		ErrInvalidSQLiteFile = errors.New("installed DB file is not a valid SQLite file")
31	
32		// ErrInvalidWALFile indicates the installed WAL file is not a valid SQLite WAL file.
33		ErrInvalidWALFile = errors.New("installed WAL file is not a valid SQLite WAL file")
34	)
35	
36	type installPhase int
37	
38	const (
39		installPhaseDB installPhase = iota
40		installPhaseWAL
41		installPhaseDone
42	)
43	
44	// FullSink streams snapshot bytes into files described by a FullSnapshot header.
45	type FullSink struct {
46		dir    string
47		header *proto.FullSnapshot
48	
49		phase    installPhase
50		walIndex int
51	
52		f         *os.File
53		remaining uint64
54	
55		dbFile   string
56		walFiles []string
57	
58		opened bool
59	}
60	
61	// NewFullSink creates a new FullSink object.
62	func NewFullSink(dir string, hdr *proto.FullSnapshot) *FullSink {
63		s := &FullSink{
64			dir:    dir,
65			header: hdr,
66			dbFile: filepath.Join(dir, "data.db"),
67		}
68	
69		for i := range hdr.WalHeaders {
70			walPath := filepath.Join(dir, fmt.Sprintf("data-%08d.wal", i))
71			s.walFiles = append(s.walFiles, walPath)
72		}
73		return s
74	}
75	
76	// Open opens the sink for writing.
77	func (s *FullSink) Open() error {
78		if s.opened {
79			return ErrSinkOpen
80		}
81		if err := s.validateHeader(); err != nil {
82			return err
83		}
84		if err := os.MkdirAll(s.dir, 0o755); err != nil {
85			return err
86		}
87	
88		s.opened = true
89		s.phase = installPhaseDB
90		s.walIndex = 0
91	
92		return s.openCurrent()
93	}
94	
95	// Write writes data to the sink.
96	func (s *FullSink) Write(p []byte) (int, error) {
97		if !s.opened {
98			return 0, ErrSinkNotOpen
99		}
100		if s.phase == installPhaseDone {
101			return 0, ErrUnexpectedData
102		}
103	
104		var total int
105		for len(p) > 0 {
106			if s.phase == installPhaseDone {
107				return total, ErrUnexpectedData
108			}
109			if s.f == nil {
110				if err := s.openCurrent(); err != nil {
111					return total, err
112				}
113				// If openCurrent() advanced to done (e.g. 0-byte artifacts), loop will handle it.
114				if s.phase == installPhaseDone {
115					continue
116				}
117			}
118	
119			if s.remaining == 0 {
120				// Current artifact complete; advance.
121				if err := s.advance(); err != nil {
122					return total, err
