156	// Close closes the sink. It fails if not all bytes were written.
157	func (s *FullSink) Close() error {
158		if !s.opened {
159			return ErrSinkNotOpen
160		}
161		defer func() {
162			s.opened = false
163		}()
164	
165		// If we still have bytes outstanding, this is incomplete.
166		if s.phase != installPhaseDone {
167			// Allow finalization if we're exactly at boundary.
168			if s.f != nil && s.remaining == 0 {
169				if err := s.advance(); err != nil {
170					_ = s.closeFile()
171					return err
172				}
173			}
174			if s.phase != installPhaseDone {
175				_ = s.closeFile()
176				return ErrIncomplete
177			}
178		}
